import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {any} [textContent]
 * @property {any[]} [cinematicPrimitives]
 *
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {{loadTexture(url:string):Promise<any>}} textureLoader
 * @property {(event:string, payload:any)=>void} emit
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {import('three').Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root group
  const root = new Group();

  // Aspect ratio derived from atlas source rect (512/320 = 1.6)
  const width = 1.6;
  const height = 1.0;

  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({ toneMapped: true, color: 0xffffff });

  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Hover lift (rise‑in)
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(
    plane.position,
    {
      y: '+=0.15',
      duration: 0.3,
      ease: 'power3.out',
    }
  );

  // Click press‑down animation
  const clickTimeline = gsap.timeline({ paused: true });
  clickTimeline
    .to(
      plane.scale,
      {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
      }
    )
    .to(
      plane.scale,
      {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.2,
        ease: 'power4.out',
      }
    );

  // Event handlers stored in userData
  root.userData.handlers = {
    hover: () => {
      hoverTimeline.restart();
    },
    hoverout: () => {
      hoverTimeline.reverse();
    },
    click: () => {
      clickTimeline.restart();
      ctx.emit('hub-journal.select');
    },
  };

  // Cleanup routine
  root.userData.cleanup = () => {
    hoverTimeline.kill();
    clickTimeline.kill();

    if (loadedTexture) {
      loadedTexture.dispose();
    }
    material.dispose();
    geometry.dispose();
  };

  // Apply cinematic primitives if any (none expected for this node)
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((primitive) => {
      const primitiveFn = ctx.primitives[primitive.name];
      if (primitiveFn) {
        const result = primitiveFn(root, primitive.params ?? {});
        // store for cleanup
        const prevCleanup = root.userData.cleanup;
        root.userData.cleanup = () => {
          prevCleanup && prevCleanup();
          result.cleanup && result.cleanup();
        };
      }
    });
  }

  return root;
}
